[CmdletBinding(SupportsShouldProcess)]
param([ValidateSet('Audit','Apply','Rollback')][string]$Mode='Audit',[Parameter(Mandatory)][string]$BindAddress,[Parameter(Mandatory)][string]$RemoteCidr,[int]$Port=3000,[string]$RuleName='Gbuzz Relay - approved LAN only',[string]$AuditPath='C:\ProgramData\Gbuzz\security-audit\lan-boundary.json',[switch]$OwnerApprovedCidr)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot LanSecurity.psm1) -Force;Assert-GbuzzLanBoundary $BindAddress $RemoteCidr;if($Mode-eq'Apply'-and-not$OwnerApprovedCidr){throw 'Apply requires -OwnerApprovedCidr for the exact narrow CIDR.'};$rules=@(Get-NetFirewallRule -DisplayName $RuleName -ErrorAction SilentlyContinue)
$candidateRules=@(Get-NetFirewallPortFilter -ErrorAction Stop|?{$_.Protocol-eq'TCP'-and($_.LocalPort-eq'Any'-or$_.LocalPort-eq[string]$Port)}|Get-NetFirewallRule|?{$_.Enabled-eq'True'-and$_.Direction-eq'Inbound'-and$_.Action-eq'Allow'-and$_.DisplayName-ne$RuleName})
$overlap=@($candidateRules|%{$r=$_;$p=$_|Get-NetFirewallPortFilter;$a=$_|Get-NetFirewallAddressFilter;if(@($a.LocalAddress)-contains'Any'-or@($a.LocalAddress)-contains'0.0.0.0/0'-or@($a.LocalAddress)-contains$BindAddress){[ordered]@{name=$r.DisplayName;local_port=$p.LocalPort;local_address=@($a.LocalAddress);remote_address=@($a.RemoteAddress)}}})
if($Mode-eq'Rollback'){if($rules-and$PSCmdlet.ShouldProcess($RuleName,'Remove managed rule')){$rules|Remove-NetFirewallRule};return};if($rules.Count-gt1){throw 'Multiple managed firewall rules found.'}
$ok=$false;if($rules.Count-eq1){$p=$rules|Get-NetFirewallPortFilter;$a=$rules|Get-NetFirewallAddressFilter;$ok=$rules.Enabled-eq'True'-and$rules.Direction-eq'Inbound'-and$rules.Action-eq'Allow'-and$p.Protocol-eq'TCP'-and$p.LocalPort-eq[string]$Port-and$a.LocalAddress-eq$BindAddress-and$a.RemoteAddress-eq$RemoteCidr}
if($Mode-eq'Audit'){[ordered]@{bind=$BindAddress;cidr=$RemoteCidr;port=$Port;managed_rule_compliant=$ok;overlapping_allow_rules=$overlap;compliant=$ok-and-not$overlap.Count}|ConvertTo-Json -Depth 5;return};if($overlap){throw "Overlapping inbound allows must be narrowed: $($overlap.name-join', ')"};if($rules-and$PSCmdlet.ShouldProcess($RuleName,'Replace managed rule')){$rules|Remove-NetFirewallRule};if($PSCmdlet.ShouldProcess($RuleName,'Create LAN-only rule')){New-NetFirewallRule -DisplayName $RuleName -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Port -LocalAddress $BindAddress -RemoteAddress $RemoteCidr -Profile Private|Out-Null};$d=Split-Path $AuditPath;if($PSCmdlet.ShouldProcess($d,'Create audit directory')){New-Item -ItemType Directory -Force $d|Out-Null};if($PSCmdlet.ShouldProcess($AuditPath,'Write evidence')){[ordered]@{applied_at=[DateTimeOffset]::UtcNow.ToString('o');bind=$BindAddress;cidr=$RemoteCidr;port=$Port;overlap_count=0}|ConvertTo-Json|Set-Content $AuditPath -Encoding utf8}
